#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#define MAX_URI_LEN 2048
#define MAX_REDIRECTS 32
#define ROLE_ADMIN 0x01
#define ROLE_OPERATOR 0x02
#define ROLE_VIEWER 0x04

typedef struct {
    char uri[MAX_URI_LEN];
    unsigned int flags;
} redirect_entry_t;

typedef struct {
    char client_id[64];
    char username[128];
    unsigned char role_mask;
    redirect_entry_t allowed_redirects[MAX_REDIRECTS];
    int num_redirects;
} oauth_client_t;

typedef struct {
    char container_id[64];
    unsigned char required_role;
    char orchestration_endpoint[256];
} container_action_t;

static int normalize_uri(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    size_t input_len = strlen(input);

    while (i < input_len && j < outlen - 1) {
        if (input[i] == '%' && i + 2 < input_len &&
            isxdigit((unsigned char)input[i+1]) &&
            isxdigit((unsigned char)input[i+2])) {
            char hex[3] = { input[i+1], input[i+2], '\0' };
            unsigned int val = (unsigned int)strtoul(hex, NULL, 16);
            if (val == 0) {
                /* Reject NUL-byte injection via encoding */
                return -1;
            }
            if (val == 0x2F) { /* encoded slash */
                output[j++] = '/';
            } else if (val == 0x2E) { /* encoded dot */
                output[j++] = '.';
            } else {
                output[j++] = (char)val;
            }
            i += 3;
        } else {
            output[j++] = input[i++];
        }
    }
    output[j] = '\0';
    return (int)j;
}

static bool uri_scheme_matches(const char *uri, const char *scheme) {
    size_t slen = strlen(scheme);
    return strncasecmp(uri, scheme, slen) == 0;
}

static bool validate_redirect_origin(const char *normalized_uri, const char *allowed_host) {
    const char *host_start = NULL;

    if (uri_scheme_matches(normalized_uri, "https://")) {
        host_start = normalized_uri + 8;
    } else if (uri_scheme_matches(normalized_uri, "http://")) {
        host_start = normalized_uri + 7;
    } else {
        return false;
    }

    size_t allowed_len = strlen(allowed_host);
    size_t host_portion_len = 0;
    const char *p = host_start;
    while (*p && *p != '/' && *p != '?' && *p != '#' && *p != ':') {
        host_portion_len++;
        p++;
    }

    /* Check if the host ends with the allowed host (subdomain matching) */
    if (host_portion_len >= allowed_len) {
        const char *suffix = host_start + (host_portion_len - allowed_len);
        if (strncasecmp(suffix, allowed_host, allowed_len) == 0) {
            /* Ensure it's a proper subdomain boundary or exact match */
            if (host_portion_len == allowed_len || 
                (suffix > host_start && *(suffix - 1) == '.')) {
                return true;
            }
        }
    }
    return false;
}

static bool check_role_authorization(const oauth_client_t *client, 
                                      const container_action_t *action) {
    return (client->role_mask & action->required_role) != 0;
}

int authorize_oauth_redirect(const oauth_client_t *client,
                             const char *requested_redirect,
                             const container_action_t *action,
                             char *approved_redirect,
                             size_t approved_len) {
    char normalized[MAX_URI_LEN];
    char allowed_normalized[MAX_URI_LEN];

    if (!client || !requested_redirect || !action || !approved_redirect) {
        return -1;
    }

    /* Step 1: Role-based access control check */
    if (!check_role_authorization(client, action)) {
        return -2; /* Insufficient privileges */
    }

    /* Step 2: Normalize the requested redirect URI */
    int norm_len = normalize_uri(requested_redirect, normalized, sizeof(normalized));
    if (norm_len <= 0) {
        return -3;
    }

    /* Step 3: Require HTTPS for all redirects */
    if (!uri_scheme_matches(normalized, "https://")) {
        return -5; /* Only HTTPS redirects allowed */
    }

    /* Step 4: Check against allowed redirect list */
    for (int i = 0; i < client->num_redirects; i++) {
        if (normalize_uri(client->allowed_redirects[i].uri, allowed_normalized, 
                     sizeof(allowed_normalized)) <= 0) {
            continue;
        }

        /* Extract host from allowed redirect for origin validation */
        const char *allowed_host = NULL;
        if (uri_scheme_matches(allowed_normalized, "https://")) {
            allowed_host = allowed_normalized + 8;
        } else if (uri_scheme_matches(allowed_normalized, "http://")) {
            allowed_host = allowed_normalized + 7;
        }

        if (allowed_host) {
            char host_buf[256] = {0};
            int k = 0;
            while (allowed_host[k] && allowed_host[k] != '/' && 
                   allowed_host[k] != '?' && allowed_host[k] != ':' && k < 255) {
                host_buf[k] = allowed_host[k];
                k++;
            }
            host_buf[k] = '\0';

            if (validate_redirect_origin(normalized, host_buf)) {
                /* Match found - use the REQUESTED URI (post-normalization) */
                strncpy(approved_redirect, normalized, approved_len - 1);
                approved_redirect[approved_len - 1] = '\0';
                return 0;
            }
        }
    }

    return -4; /* No matching redirect URI */
}

/* Container orchestration callback after OAuth approval */
int execute_container_action(const char *approved_redirect,
                             const container_action_t *action) {
    /* In production, this would issue the OAuth token and redirect */
    printf("[ORCH] Issuing token for container '%s' via endpoint '%s'\n",
           action->container_id, action->orchestration_endpoint);
    printf("[ORCH] Redirecting to: %s\n", approved_redirect);
    /* Token is appended to redirect URI as fragment */
    return 0;
}

